<script setup>
import {ref,reactive,onMounted,computed} from 'vue';
import {useRoute} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import {fetchAddresses,createAddress,updateAddress,deleteAddress,setDefaultAddress} from '../api';
const route=useRoute(),list=ref([]),loading=ref(true),busy=ref(false),error=ref(''),dialog=ref(false),editing=ref(null),formRef=ref();
const blank=()=>({receiverName:'',phone:'',province:'',city:'',district:'',detail:'',label:'学校',isDefault:false});
const form=reactive(blank());
const returnTo=computed(()=>typeof route.query.redirect==='string'&&route.query.redirect.startsWith('/')&&!route.query.redirect.startsWith('//')?route.query.redirect:null);
const rules={receiverName:[{required:true,message:'请输入收货人',trigger:'blur'},{max:30,message:'最多30字',trigger:'blur'}],phone:[{required:true,message:'请输入手机号',trigger:'blur'},{pattern:/^1[3-9]\d{9}$/,message:'请输入正确的11位手机号',trigger:'blur'}],province:[{required:true,message:'请填写省份',trigger:'blur'}],city:[{required:true,message:'请填写城市',trigger:'blur'}],district:[{required:true,message:'请填写区县',trigger:'blur'}],detail:[{required:true,message:'请填写详细地址',trigger:'blur'},{max:200,message:'详细地址最多200字',trigger:'blur'}]};
async function load(){loading.value=true;error.value='';try{list.value=await fetchAddresses();}catch{error.value='暂时无法读取地址，请重试。';}finally{loading.value=false;}}
function edit(address){editing.value=address?.id||null;Object.assign(form,address?{...address,isDefault:!!address.isDefault}:blank());dialog.value=true;}
async function save(){if(busy.value||!await formRef.value.validate().catch(()=>false))return;busy.value=true;try{await (editing.value?updateAddress(editing.value,{...form}):createAddress({...form}));ElMessage.success('地址已保存');dialog.value=false;await load();}catch{}finally{busy.value=false;}}
async function remove(a){try{await ElMessageBox.confirm('删除此地址？已创建订单中的地址不会改变。','删除地址',{type:'warning'});await deleteAddress(a.id);ElMessage.success('地址已删除');await load();}catch{}}
async function makeDefault(a){if(busy.value)return;busy.value=true;try{await setDefaultAddress(a.id);await load();ElMessage.success('默认地址已更新');}catch{}finally{busy.value=false;}}
onMounted(load);
</script>
<template><div class="page"><div class="container address-page"><div class="page-heading"><span class="eyebrow">YOUR DELIVERY BOOK</span><h1>地址管理</h1><p>保存常用地址，让每一次好物交接更顺利。</p></div><div class="section-heading"><span class="text-sub">{{list.length}} 个收货地址</span><el-button type="primary" @click="edit(null)">新增地址</el-button></div><div v-if="error" class="inline-error">{{error}}<el-button @click="load">重新加载</el-button></div><el-skeleton v-else-if="loading" :rows="6" animated/><div v-else-if="list.length" class="address-grid"><article v-for="a in list" :key="a.id" class="address-card card" :class="{default:a.isDefault}"><div class="address-person"><strong>{{a.receiverName}}</strong><span>{{a.phone}}</span><el-tag v-if="a.isDefault" type="success" size="small">默认</el-tag></div><p>{{a.province}}{{a.city}}{{a.district}}</p><p class="address-detail">{{a.detail}}</p><div class="address-bottom"><span>{{a.label||'常用地址'}}</span><div><el-button v-if="!a.isDefault" text :disabled="busy" @click="makeDefault(a)">设为默认</el-button><el-button text @click="edit(a)">编辑</el-button><el-button text type="danger" @click="remove(a)">删除</el-button></div></div></article></div><div v-else class="empty-block card"><el-icon><Location/></el-icon><h3>还没有收货地址</h3><p>添加后可以在邮寄下单时直接选择。</p><el-button type="primary" @click="edit(null)">添加第一个地址</el-button></div><RouterLink v-if="returnTo" class="return-checkout outline-button" :to="returnTo">返回商品继续下单</RouterLink><p class="order-note">地址只用于你发起的邮寄交易，其他用户无法查看你的地址簿。</p></div><el-dialog v-model="dialog" :title="editing?'编辑收货地址':'新增收货地址'" width="min(590px,94vw)" :close-on-click-modal="!busy" :show-close="!busy"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="address-form-grid"><el-form-item label="收货人" prop="receiverName"><el-input v-model="form.receiverName" maxlength="30"/></el-form-item><el-form-item label="手机号" prop="phone"><el-input v-model="form.phone" maxlength="11" inputmode="tel"/></el-form-item></div><div class="address-region-grid"><el-form-item label="省份" prop="province"><el-input v-model="form.province" maxlength="30" placeholder="如：浙江省"/></el-form-item><el-form-item label="城市" prop="city"><el-input v-model="form.city" maxlength="30" placeholder="如：杭州市"/></el-form-item><el-form-item label="区县" prop="district"><el-input v-model="form.district" maxlength="30" placeholder="如：西湖区"/></el-form-item></div><el-form-item label="详细地址" prop="detail"><el-input v-model="form.detail" type="textarea" :rows="3" maxlength="200" show-word-limit placeholder="街道、门牌号或宿舍楼及房间号"/></el-form-item><el-form-item label="地址标签"><el-input v-model="form.label" maxlength="20" placeholder="学校 / 家 / 常用"/></el-form-item><el-checkbox v-model="form.isDefault">设为默认收货地址</el-checkbox></el-form><template #footer><el-button :disabled="busy" @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存地址</el-button></template></el-dialog></div></template>
